package com.prayerdraintimer;

import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import java.awt.*;
import java.awt.geom.Arc2D;

public class PrayerDrainTimerOverlay extends Overlay {

    private Client client;
    private PrayerDrainTimerPlugin plugin;
    private PrayerDrainTimerConfig config;

    private long lastnano;
    private float delta;

    PrayerDrainTimerOverlay(Client client, PrayerDrainTimerPlugin plugin, PrayerDrainTimerConfig config) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;

        lastnano = System.nanoTime();
        delta = 0;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        updateDelta();
        plugin.render();

        graphics.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);

        Widget widget = client.getWidget(InterfaceID.Orbs.ORB_PRAYER);
        if (widget == null || widget.isHidden()) {
            widget = client.getWidget(InterfaceID.OrbsNomap.ORB_PRAYER);
        }
        if (widget != null && !widget.isHidden()) {
            Rectangle bounds = widget.getBounds();

            float percent = plugin.getPercent();

            Arc2D.Double arc = new Arc2D.Double(bounds.x + 27, bounds.y + (bounds.height / 2f - 26D / 2), 26D, 26D, 90.d, -360.d * percent, Arc2D.OPEN);
            final Stroke STROKE = new BasicStroke(2f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER);
            graphics.setStroke(STROKE);

            Color meterColor = config.meterColor();
            if (client.getBoostedSkillLevel(Skill.PRAYER) <= config.lowMeterThreshold() && client.getRealSkillLevel(Skill.PRAYER) > config.lowMeterThreshold())
                meterColor = config.lowMeterColor();
            if (plugin.isCalibrating())
                meterColor = config.unknownMeterColor();
            graphics.setColor(meterColor);

            graphics.draw(arc);

            if (config.showDrain()) {
                String top = Integer.toString(plugin.getDrainAmount());
                if (plugin.isCalibrating())
                    top = "?";
                String bot = Integer.toString(plugin.getDrainResistance());

                graphics.setFont(FontManager.getRunescapeSmallFont());
                FontMetrics fontMetrics = graphics.getFontMetrics();

                int topWidth = fontMetrics.stringWidth(top);
                int botWidth = fontMetrics.stringWidth(bot);
                int height = fontMetrics.getHeight();

                graphics.setColor(Color.black);
                graphics.drawString(top, (float) bounds.getCenterX() + 12f - topWidth / 2f, (float) bounds.getCenterY() + 1);
                graphics.drawString(bot, (float) bounds.getCenterX() + 12f - botWidth / 2f, (float) bounds.getCenterY() + height + 1);

                graphics.setColor(config.drainTextColor());
                graphics.drawString(top, (float) bounds.getCenterX() + 11f - topWidth / 2f, (float) bounds.getCenterY());
                graphics.drawString(bot, (float) bounds.getCenterX() + 11f - botWidth / 2f, (float) bounds.getCenterY() + height);
            }
        }

        return null;
    }

    public float delta() {
        return delta;
    }

    private void updateDelta() {
        long nano = System.nanoTime();
        delta = (nano - lastnano) / 1000000000f;
        lastnano = nano;
    }
}

