package com.prayerdraintimer;

import com.google.inject.Provides;

import javax.inject.Inject;

import lombok.AccessLevel;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.WorldService;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.api.events.GameTick;
import net.runelite.client.plugins.worldhopper.ping.Ping;
import net.runelite.client.ui.overlay.OverlayManager;

import java.util.*;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

@Slf4j
@PluginDescriptor(
        name = "Prayer Drain Timer"
)
public class PrayerDrainTimerPlugin extends Plugin {
    @Inject
    private Client client;

    @Inject
    private PrayerDrainTimerConfig config;

    @Inject
    private ItemManager itemManager;

    @Inject
    private WorldService worldService;

    @Inject
    private OverlayManager overlayManager;

    private PrayerDrainTimerOverlay overlay;


    @Getter(AccessLevel.PACKAGE)
    @Setter(AccessLevel.PACKAGE)
    private int prayerBonus;

    private int lastTickPrayer = 0;
    private int drainAmount = 0;
    private List<PrayerTime> prayerTimes = new ArrayList<PrayerTime>();
    private List<Prayer> ignoreNextVarbit = new ArrayList<Prayer>();
    private List<Prayer> ignoreNextIncompatible = new ArrayList<>();
    private int ping = -1;
    private int checksTilPing = 0;
    private ScheduledExecutorService pingThreads;
    private int externalPrayerDrain = 0;
    private int currentPlayerAnim = -1;
    private boolean fullRestoreExtraTick = false;
    private boolean justDied = false;
    private Map<Prayer, Set<PrayerGroup>> incompatiblePrayers = new HashMap<>();
    private List<Prayer> prayersByRecency = new ArrayList<>();
    private boolean isCalibrating = true;

    private static class PrayerTime {
        public Prayer type;
        public float time;

        PrayerTime(Prayer type, float delay) {
            this.type = type;
            this.time = 0;
        }
    }

    private enum PrayerGroup {
        OVERHEADS,
        DEFENCE,
        STRENGTH,
        ACCURACY,
    }

    public PrayerDrainTimerPlugin() {
        pingThreads = Executors.newScheduledThreadPool(20);
    }

    @Override
    protected void startUp() throws Exception {
        // todo: refactor this to have a distinct "server simulator" that handles emulating all serverside logic
        // would simplify a lot of the network & server-processing lag logic, because it can just handle it once

        overlay = new PrayerDrainTimerOverlay(client, this, config);
        overlayManager.add(overlay);
        setupIncompatiblePrayers();
        setupPrayersByRecency();

        isCalibrating = true;
    }

    @Override
    protected void shutDown() throws Exception {
        overlayManager.remove(overlay);
    }

    @Subscribe
    public void onGameTick(GameTick tick) {
        update();

        pingThreads.schedule(this::updatePing, 0, TimeUnit.SECONDS);
    }

    public void render() {
        updateEvents();
    }

    public void update() {
        int currentPrayer = client.getBoostedSkillLevel(Skill.PRAYER);
        boolean prayerChanged = currentPrayer != lastTickPrayer;
        int prayerDelta = lastTickPrayer - currentPrayer;

        int drainRate = getDrainEffect(client);
        int drainResistance = getDrainResistance();

        if (drainAmount < 0)
            drainAmount = 0;

        if (client.getBoostedSkillLevel(Skill.PRAYER) == 0)
            drainAmount = 0;

        // todo: figure out this "full restore extra tick" mechanic
        // i think it's really just an added buffer of 12 drain points, or something
        // since there's an extra tick of drain for protection prayers
        // but not with prot prayer + thick skin, or higher drain prayers
        if (drainAmount < drainResistance && (!fullRestoreExtraTick || drainRate > 12))
            drainAmount += drainRate;

        if (drainRate > 0 && fullRestoreExtraTick)
            fullRestoreExtraTick = false;

        // if it drained normally
        // filter out fightcave bats and such with externalPrayerDrain
        // since they also reduce prayer by 1, but don't reset drain
        if (prayerDelta == 1 + externalPrayerDrain) {
            drainAmount -= drainResistance;
            isCalibrating = false;
        }

        if (justDied && currentPrayer == client.getRealSkillLevel(Skill.PRAYER)) {
            justDied = false;
            drainAmount = 0;
            isCalibrating = false;
        }

        // if we restored prayer to max
        // drinking a prayer pot to full does NOT reset the drain
        // but altars and restoration pools do reset drain
        boolean isFullRestoreAnim = (currentPlayerAnim == 645 /* altar */ || currentPlayerAnim == 7305 /* restoration pool */);
        boolean isNewPrayerMax = currentPrayer >= client.getRealSkillLevel(Skill.PRAYER);
        boolean wasOldPrayerMax = lastTickPrayer >= client.getRealSkillLevel(Skill.PRAYER); // edge case for places like monastery altar
        if (prayerChanged && isNewPrayerMax && !wasOldPrayerMax && isFullRestoreAnim) {
            drainAmount = 0;

            // weird but this seems to be correct behaviour
            // altars keep the extra tick always, including while praying
            // pools only keep it if you're not currently praying
            if (drainRate == 0 || currentPlayerAnim == 645) {
                fullRestoreExtraTick = true;
            }
            isCalibrating = false;
        }
        // todo: extreme edge case, monastery altar max+2 -> max+1 same tick as restore
        // will not reset drain even though it should in that specific instance
        // todo: restoration pool with max prayer should still reset drain

        lastTickPrayer = currentPrayer;
        externalPrayerDrain = 0;
        cleanEvents();
    }

    @Subscribe
    public void onAnimationChanged(AnimationChanged e) {
        // need to handle external sources of prayer drain manually
        // sucks but what can ya do

        if (e.getActor().getName().equals("Tz-Kih") && e.getActor().getAnimation() == 2621) // firebat attack
        {
            externalPrayerDrain += 1;
        }

        if (e.getActor() == client.getLocalPlayer()) {
            currentPlayerAnim = e.getActor().getAnimation();
        }
    }

    public void updateEvents() {
        float delta = overlay.delta();

        for (PrayerTime prayerTime : prayerTimes) {
            prayerTime.time -= delta;
        }
    }

    public boolean wasPrayerTurnedOnThisTick(Prayer prayer) {
        for (PrayerTime prayerTime : prayerTimes) {
            if (prayerTime.type == prayer && prayerTime.time < 0)
                return true;
        }

        return false;
    }

    public void cleanEvents() {
        for (int i = prayerTimes.size() - 1; i >= 0; i--) {
            if (prayerTimes.get(i).time < 0) {
                prayerTimes.remove(i);
            }
        }
    }

    public float getPercent() {
        if (client.getBoostedSkillLevel(Skill.PRAYER) == 0)
            return 0f;

        if (isCalibrating)
            return 1f;

        float resistance = getDrainResistance();
        return clamp((resistance - drainAmount) / resistance, 0, 1);
    }

    @Provides
    PrayerDrainTimerConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(PrayerDrainTimerConfig.class);
    }

    @Subscribe
    public void onItemContainerChanged(final ItemContainerChanged event) {
        // modified from runelite's default prayer plugin
        final int id = event.getContainerId();
        if (id == InventoryID.EQUIPMENT.getId()) {
            prayerBonus = totalPrayerBonus(event.getItemContainer().getItems());
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event) {
        boolean printed = false;
        for (PrayerType prayerType : PrayerType.values()) {
            if (prayerType.isActive(client)) {
                printed = true;
            }
        }

        for (Prayer prayer : Prayer.values()) {
            if (event.getVarbitId() == prayer.getVarbit() && event.getValue() == 1) {
                // we want to use varbits to tell when we actually prayed
                // but clicking on the prayer buttons doubles them up
                // one immediately (don't want) and one as server response (do want)
                // so we ignore the first varbit after a prayer button click
                boolean isIgnored = false;
                for (int i = ignoreNextVarbit.size() - 1; i >= 0 && !isIgnored; i--) {
                    if (ignoreNextVarbit.get(i) == prayer) {
                        isIgnored = true;
                        ignoreNextVarbit.remove(i);
                    }
                }

                // we also need to make sure we didn't switch off an (active) incompatible prayer
                // because we still drain in that case, it doesn't count as a prayer flick
                // unless that other prayer isn't draining yet either
                boolean isIncompatible = false;
                if (incompatiblePrayers.containsKey(prayer)) {
                    for (Prayer other : Prayer.values()) {
                        if (other != prayer && incompatiblePrayers.containsKey(other)) {
                            var intersection = new HashSet<>(incompatiblePrayers.get(prayer));
                            intersection.retainAll(incompatiblePrayers.get(other));

                            boolean isIgnoringOther = false;
                            for (Prayer value : ignoreNextIncompatible) {
                                if (value == other) {
                                    isIgnoringOther = true;
                                }
                            }

                            if (!intersection.isEmpty() && client.isPrayerActive(other) && !isIgnoringOther)
                                isIncompatible = true;
                        }
                    }
                }

                // this check is only true the first varbit event, so we need to delay
                boolean hadIncompatible = false;
                for (int i = ignoreNextIncompatible.size() - 1; i >= 0; i--) {
                    if (ignoreNextIncompatible.get(i) == prayer) {
                        hadIncompatible = true;
                        ignoreNextIncompatible.remove(i);
                    }
                }

                if (!isIgnored)
                    markPrayerAsRecent(prayer);

                if (!isIgnored && !hadIncompatible) {
                    float inputDelay = getInputDelay() * (config.pingInfluencePercent() / 100f);
                    float serverDelay = getServerDelay() * (config.playerInfluencePercent() / 100f);
                    prayerTimes.add(new PrayerTime(prayer, inputDelay + serverDelay));
                } else if (isIncompatible) {
                    ignoreNextIncompatible.add(prayer);
                }
            }
        }
    }


    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked e) {
        if (e.getMenuOption().equals("Activate")) {
            String target = removeFormatting(e.getMenuTarget()).toLowerCase();

            for (PrayerType prayerType : PrayerType.values()) {
                if (prayerType.getName().toLowerCase().equals(target)) {
                    ignoreNextVarbit.add(prayerType.getPrayer());
                }
            }
        }
    }

