    private String removeFormatting(String raw) {
        return raw.replaceAll("<[^>]*>", "");
    }

    public int getDrainAmount() {
        if (drainAmount < 0)
            return 0;

        if (drainAmount >= getDrainResistance())
            return getDrainResistance();

        return drainAmount;
    }

    public int getDrainResistance() {
        return 60 + 2 * prayerBonus;
    }

    private int totalPrayerBonus(Item[] items) {
        // from runelite's default prayer plugin
        int total = 0;
        for (Item item : items) {
            var is = itemManager.getItemStats(item.getId());
            if (is != null && is.getEquipment() != null) {
                total += is.getEquipment().getPrayer();
            }
        }
        return total;
    }

    private int getDrainEffect(Client client) {
        // modified from runelite's default prayer plugin

        // if any prayer is active then flicking doesn't work
        boolean isActivePrayer = false;
        for (PrayerType prayerType : PrayerType.values()) {
            Prayer prayer = prayerType.getPrayer();
            if (prayerType.isActive(client) && !wasPrayerTurnedOnThisTick(prayer)) {
                isActivePrayer = true;
            }
        }
        if (!isActivePrayer)
            return 0;

        // todo: fix edge case where switching between incompatible prayers might not drain, sometimes
        int drainEffect = 0;
        for (PrayerType prayerType : PrayerType.values()) {
            Prayer prayer = prayerType.getPrayer();
            if (prayerType.isActive(client) && isMostRecentPrayerOfGroup(prayer)) {
                drainEffect += prayerType.getDrainEffect();
            }
        }
        return drainEffect;
    }

    private float getInputDelay() {
        float delay = (ping / 1000f);
        return Math.min(delay, (config.pingMax() / 1000f));
    }

    private void updatePing() {
        if (checksTilPing == 0) {
            int currentping = sendPing();

            if (currentping != -1) {
                ping = currentping;
                checksTilPing = config.pingCount() - 1;
            }
        } else {
            checksTilPing--;
        }
    }

    private int sendPing() {
        return Ping.ping(worldService.getWorlds().findWorld(client.getWorld()));
    }

    private int getPlayerCount() {
        return worldService.getWorlds().findWorld(client.getWorld()).getPlayers();
    }

    private float getServerDelay() {
        int playercount = getPlayerCount();

        return config.prayerMult() / 1000f * playercount / 1000f + config.prayerConst() / 1000f;
    }

    private float clamp(float value, float low, float high) {
        if (value < low)
            return low;

        if (value > high)
            return high;

        return value;
    }

