    private void setupPrayersByRecency() {
        prayersByRecency = new ArrayList<>();

        // order doesn't matter initially, only after we start praying
        for (Prayer prayer : Prayer.values()) {
            prayersByRecency.add(prayer);
        }
    }

    private void markPrayerAsRecent(Prayer prayer) {
        for (int i = prayersByRecency.size() - 1; i >= 0; i--) {
            if (prayersByRecency.get(i) == prayer) {
                prayersByRecency.remove(i);
                break;
            }
        }

        prayersByRecency.add(0, prayer);
    }

    private boolean isMostRecentPrayerOfGroup(Prayer prayer) {
        int index = prayersByRecency.indexOf(prayer);

        if (!incompatiblePrayers.containsKey(prayer))
            return true;

        for (PrayerGroup group : incompatiblePrayers.get(prayer)) {
            for (int i = 0; i < index; i++) {
                var current = prayersByRecency.get(i);

                if (client.isPrayerActive(current) && incompatiblePrayers.containsKey(current)) {
                    for (PrayerGroup other : incompatiblePrayers.get(current)) {
                        if (other == group) {
                            return false;
                        }
                    }
                }
            }
        }

        return true;
    }
